51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ then 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    private String email;
57	
58	    @Column(name = "registration_date")
