123	    /**
124	     * The stored {@link #getTelephone() telephone} formatted for humans by {@link TelephoneFormatter}:
125	     * the country code, a space, then the national digits grouped in threes (e.g. {@code +61412345678}
126	     * -> {@code +61 412 345 678}). The raw {@link #getTelephone() telephone} stays in E.164 form.
127	     */
128	    public String getTelephoneDisplay() {
129	        return TelephoneFormatter.toDisplay(this.telephone);
130	    }
