148	    public LocalDate getBirthDate() {
149	        return this.birthDate;
150	    }
151	
152	    public void setBirthDate(LocalDate birthDate) {
153	        this.birthDate = birthDate;
154	    }
155	
156	    /**
157	     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
158	     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
159	     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
160	     * (so the field is absent from the response) or the registration date is unknown.
161	     */
162	    public String getAgeBand() {
163	        if (this.birthDate == null || this.registrationDate == null) {
164	            return null;
165	        }
166	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
167	        if (age < 18) {
168	            return "MINOR";
169	        }
170	        if (age < 65) {
171	            return "ADULT";
172	        }
173	        return "SENIOR";
174	    }
175	
176	    public String getCustomerCode() {
177	        return this.customerCode;
178	    }
179	
180	    public void setCustomerCode(String customerCode) {
181	        this.customerCode = customerCode;
182	    }
183	
184	    public String getMembershipNumber() {
185	        return this.membershipNumber;
186	    }
187	
188	    public void setMembershipNumber(String membershipNumber) {
189	        this.membershipNumber = membershipNumber;
190	    }
191	
192	    public String getHouseholdId() {
193	        return this.householdId;
194	    }
