208	    /**
209	     * Sets the number of owners that belong to this owner's household (same last name and postcode; see
210	     * {@link org.springframework.samples.petclinic.rest.function.owner.Household}), including this owner.
211	     * Computed per request and used only by {@link #getMembershipPoints()} — a household of three or more
212	     * contributes points. Not persisted and not serialized into the response (no getter is exposed); the
213	     * count is recomputed on each read because household membership changes as owners come and go.
214	     */
215	    public void setHouseholdSize(Integer householdSize) {
216	        this.householdSize = householdSize;
217	    }
218	
219	    /**
220	     * Whether this response should carry a bulk-signup warning: {@code true} when more than 80 owners
221	     * have already been created for this owner's registration day. Computed per request, not persisted.
222	     */
223	    public Boolean getBulkSignupWarning() {
224	        return this.bulkSignupWarning;
225	    }
226	
227	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
228	        this.bulkSignupWarning = bulkSignupWarning;
229	    }
230	
231	    /**
232	     * Whether this owner is a <em>possible</em> (soft) duplicate of another owner: {@code true} when some
233	     * other owner shares this owner's last name (case-insensitively) and postcode but has a different
234	     * telephone — a near match. Always false for an owner admitted as a declared household member (via
235	     * {@code sharesHousehold}), which is not a suspected duplicate.
236	     * Computed per request, not persisted. See {@link #getPossibleDuplicateOf()} for the matched owner.
237	     */
238	    public Boolean getPossibleDuplicate() {
239	        return this.possibleDuplicate;
240	    }
241	
242	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
243	        this.possibleDuplicate = possibleDuplicate;
244	    }
245	
246	    /**
247	     * The id of the existing owner this owner possibly duplicates (same last name and postcode, different
248	     * telephone), or {@code null} when {@link #getPossibleDuplicate() possibleDuplicate} is false. When
249	     * several owners match, this is the earliest (lowest id). Computed per request, not persisted.
250	     */
251	    public Integer getPossibleDuplicateOf() {
252	        return this.possibleDuplicateOf;
253	    }
254	
255	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
256	        this.possibleDuplicateOf = possibleDuplicateOf;
257	    }
258	
259	    /**
260	     * The owner's membership points: start at 0; add 2 when an email is present; add 1 when
261	     * {@code namesakeCount} is 0; add 2 for a household of 3 or more members (see
262	     * {@link #setHouseholdSize(Integer)}); add 3 for tenure of more than 365 days (measured from
263	     * {@code registrationDate} to today). A newly created owner has zero tenure, so a fresh owner scores
264	     * at most 5 points (2 + 1 + 2).
265	     */
266	    public int getMembershipPoints() {
267	        int points = 0;
268	        boolean hasEmail = this.email != null && !this.email.isBlank();
269	        if (hasEmail) {
270	            points += 2;
271	        }
272	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
273	        if (unique) {
274	            points += 1;
275	        }
276	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
277	        if (largeHousehold) {
278	            points += 2;
279	        }
280	        boolean tenured = this.registrationDate != null
281	            && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
282	        if (tenured) {
283	            points += 3;
284	        }
285	        return points;
286	    }
287	
288	    /**
289	     * The owner's membership level, derived from {@link #getMembershipPoints() membershipPoints}:
290	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
291	     */
292	    public int getMembershipLevel() {
293	        int points = getMembershipPoints();
294	        if (points <= 1) {
295	            return 1;
296	        }
297	        if (points <= 3) {
298	            return 2;
299	        }
300	        if (points <= 5) {
301	            return 3;
302	        }
303	        return 4;
304	    }
305	
306	    /**
307	     * Fixed city-to-region table mapping each known city to its canonical region string.
308	     */
309	    private static final Map<String, String> CITY_REGION = Map.of(
310	        "Sydney", "NSW",
311	        "Melbourne", "VIC",
312	        "Brisbane", "QLD");
313	
314	    /**
315	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
316	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
317	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
318	     */
319	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
320	        "NSW", new int[] {2000, 2099},
321	        "VIC", new int[] {3000, 3099},
322	        "QLD", new int[] {4000, 4099});
323	
324	    /**
325	     * Fixed region-to-timezone table mapping each known region to its IANA timezone name
326	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). The single
327	     * source of truth for the timezone derivation read by {@link #getTimezone()}.
328	     */
329	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
330	        "NSW", "Australia/Sydney",
331	        "VIC", "Australia/Melbourne",
332	        "QLD", "Australia/Brisbane");
333	
334	    /**
335	     * The canonical region for {@code city} derived from the fixed city-to-region table
336	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
337	     * city is not in the table. The single source of truth for the create-time postcode range check in
338	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
339	     */
340	    public static String regionOf(String city) {
341	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
342	    }
343	
344	    /**
345	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
346	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
347	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
348	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
349	     * postcode range check.
350	     */
351	    public static int[] postcodeRangeOf(String region) {
352	        return REGION_POSTCODES.get(region);
353	    }
354	
355	    /**
356	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
357	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
358	     * range.
359	     */
360	    public static String regionOfPostcode(String postcode) {
361	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
362	            return null;
363	        }
364	        int value = Integer.parseInt(postcode);
365	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
366	            int[] range = entry.getValue();
367	            if (value >= range[0] && value <= range[1]) {
368	                return entry.getKey();
369	            }
370	        }
371	        return null;
372	    }
373	
374	    /**
375	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
376	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
377	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
378	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
379	     * customer code is assigned.
380	     */
381	    public String getLocality() {
382	        if (this.customerCode == null) {
383	            return "UNKNOWN";
384	        }
385	        int dash = this.customerCode.indexOf('-');
386	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
387	    }
388	
389	    /**
390	     * The owner's IANA timezone, derived from the {@link #getLocality() locality}/region via the fixed
391	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
392	     * QLD -> Australia/Brisbane), or {@code null} (so the field is absent from the response) when the
393	     * locality maps to no known region.
394	     */
395	    public String getTimezone() {
396	        return REGION_TIMEZONE.get(getLocality());
397	    }
398	
399	    /**
400	     * The single Luhn check digit (0-9) computed over the digits contained in the
401	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
402	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
403	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
404	     */
405	    public int getCheckDigit() {
406	        String code = this.customerCode;
407	        if (code == null) {
408	            return 0;
409	        }
410	        int sum = 0;
411	        boolean dbl = true;
412	        for (int i = code.length() - 1; i >= 0; i--) {
413	            char c = code.charAt(i);
414	            if (c < '0' || c > '9') {
415	                continue;
416	            }
417	            int d = c - '0';
418	            if (dbl) {
419	                d *= 2;
420	                if (d > 9) {
421	                    d -= 9;
422	                }
423	            }
424	            sum += d;
425	            dbl = !dbl;
426	        }
427	        return (10 - (sum % 10)) % 10;
428	    }
429	
430	    /**
431	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
432	     * {@code "PHONE"}.
433	     */
434	    public String getContactPreference() {
435	        boolean hasEmail = this.email != null && !this.email.isBlank();
436	        return hasEmail ? "EMAIL" : "PHONE";
437	    }
438	
439	    /**
440	     * The single canonical format of an owner's derived identity key:
441	     * {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The telephone and
442	     * household id are used as given (they are expected to already be canonical: E.164 and an assigned
443	     * household id); the email is lower-cased here and a null/blank email, telephone or household id
444	     * contributes an empty component. This is the only place the {@code "|"}-join lives; the stored-owner
445	     * {@link #getIdentityKey()} routes through here so the format cannot drift. The key is a descriptive,
446	     * returned field; create-time duplicate detection itself is keyed on the household alone (see
447	     * {@code CheckHouseholdUnique}).
448	     */
449	    public static String identityKey(String telephone, String email, String householdId) {
450	        String tel = (telephone == null) ? "" : telephone;
